"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8913],{52227:e=>{e.exports=JSON.parse('{"functions":[{"name":"UnlockPerk","desc":"Unlock `perkId` for the player: validate level + points + coins, deduct the\\none-time `UnlockCost`, and mark it unlocked (which spends `UnlockPointCost`\\nfrom the perk\'s pool \u2014 points are derived). Returns (success, reasonCode).\\nUnlock changes no buffs (level is still 0), so it does NOT fire OnPerkStateChanged.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"perkId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"},{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":89,"path":"src/ServerStorage/SharedModules/PerkManager.luau"}},{"name":"AllocatePoint","desc":"Spend one point on `perkId`. Returns (success, reasonCode). No-op (with the\\nmatching reason) if the profile is missing, the perk is unknown/at max, or the\\npool has no available points.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"perkId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"},{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":120,"path":"src/ServerStorage/SharedModules/PerkManager.luau"}},{"name":"Respec","desc":"Respec a pool. `pool`: 0 = both, 1 = Personal, 2 = Party. Full reset: clears the\\npool\'s perk levels AND unlock flags, refunds each unlocked perk\'s UnlockCost\\n(exact, un-inflated), then re-seeds free starters so they stay unlocked. Points\\nare derived, so cleared levels and unlock point costs return to the wallet\\nautomatically.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"pool","desc":"","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":144,"path":"src/ServerStorage/SharedModules/PerkManager.luau"}},{"name":"GetPerkLevels","desc":"The player\'s persisted perk levels (live reference; read-only by convention).\\nReturns an empty table if no profile is loaded.","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"{ [string]: number }\\n"}],"function_type":"static","source":{"line":174,"path":"src/ServerStorage/SharedModules/PerkManager.luau"}},{"name":"Initialize","desc":"Wire profile lifecycle, packet handlers, and the level-up resend. Call once.","params":[],"returns":[],"function_type":"static","source":{"line":213,"path":"src/ServerStorage/SharedModules/PerkManager.luau"}}],"properties":[],"types":[],"name":"PerkManager","desc":"Authority for player perk allocation and unlock. Owns the `PlayerPerks`\\nProfileStore (one session per player, key = UserId), validates\\nunlock/allocate/respec with the pure `PerkState` (reading the player\'s level\\nfrom `XPManager` and coin balance from `CoinManager`), and replicates the\\nowning player\'s snapshot via `PerkStateSync`. Points are derived, never\\nstored \u2014 `PerkLevels`, `Unlocked`, and `PerkSchemaVersion` persist. Allocate\\nand respec fire `Signals.OnPerkStateChanged` so `PerkEffectsDispatcher`\\nrepublishes the buff folders; unlock does not (it changes no buffs).","realm":["Server"],"source":{"line":15,"path":"src/ServerStorage/SharedModules/PerkManager.luau"}}')}}]);